@module sonority  src=sonority.lua  loc=919  mode=namespace  self=sonority

# Invariants & contracts
  @invariant  pure module: no state; ratios/cents are tuning.lua's, the placement carries them  @ 4
  @invariant  convex in the displacements, so the sweep order and the start buy speed, not the answer  @ 380
  @contract  spellings, window, strength, stiffness, start (per strand), free (strands that sweep)  @ 381
  @contract  → displacements minimising sonority.springCost, the held strands standing at their start  @ 382
  @contract  each swept displacement inside its own strand's window  @ 383
  @contract  members; seat/window/mayWait per strand; moves, width, stiffness → Spellings, best first  @ 596
  @contract  a join is one move; one offset of the spelling seats every member inside its own window  @ 597
  @contract  the width is a width per waiting set; math.huge enumerates the spellings whole  @ 598
  @contract  a sonority some member no chain reaches has no spelling: the list comes back empty  @ 599
  @contract  onsets, a spelling list per onset, seat and window per strand, strength, stiffness, cap  @ 866
  @contract  → the cheapest Answer, every answer carried extended by every spelling of the onset  @ 867
  @contract  the strands the onset sounds relax; the rest of an answer stands at the cents it carries  @ 868
  @contract  a sonority holding a waiter is charged in its own onset's slot, as its members place  @ 869
  @contract  answers agreeing to half a cent ahead and owing the same merge; the set is cut to cap  @ 870
  @contract  the cut runs over two pools, the answers that owe and the answers that have paid  @ 871
  @contract  nil where an onset has no spelling — a sonority the target can't reach refuses it  @ 872

# Shapes
  @shape  Coords = {[oddPrime]=exponent}; prime 2 is absent, so the score reads harmony not spacing  @ 5
  @shape  Strand = { notes={ {ppq,pitch,endppq,..},.. }, class=<step-class>, shortlist={ Candidate,.. } }; the walk reads the strikes, the releases and the class  @ 6
  @shape  Sonority = { ppq, strands={ strandIndex,.. } }; most recently struck first, the last n struck and whatever else still sounds  @ 7
  @shape  Candidate = { coords=Coords, strain=<distance from the written step, in half-windows> }  @ 8
  @shape  Spring = { i=<strand>, j=<strand>, delta=<cents> }; the pair is pure where d[j] - d[i] = delta  @ 302
  @shape  Window = { below=<cents to the step below>, above=<cents to the step above> }  @ 327
  @shape  State = { at={ [slot]=Placed }, components={ {slot,..},.. }, parts, key, score, lo/hi=<the offsets left open> }  @ 467
  @shape  Placed = { coords=Coords, cents=<the pure position>, deviation=<from the seat>, component }  @ 468
  @shape  Spelling = { box=<what its components carry>, springs={Spring,..}, waiting={member,..}, placed={ [strand]={ coords=Coords, component } } }  @ 595
  @shape  Onset = { ppq, members={strand,..}, sounding={strand,..}, mayWait={[strand]=true,..} }  @ 660
  @shape  Answer = { choice={ spelling per onset }, springs={ Spring list per onset }, box, displacement, cost, held={ [onset]=Held } }  @ 864
  @shape  Held = { placed={ [strand]={ coords=Coords, component } }, waiting={ [strand]=true }, box=<charged so far>, next=<free component> }  @ 865

# Imports
  @const util = 'util'  @ 10
  @const tuning = 'tuning'  @ 11

# Module-level constants
  @const sonority = {}  @ 12
  @const budget = 200000  @ 186
  @const PURE = 50  @ 323
  @const TOLERANCE, SWEEPS = 1e-4, 1000  @ 351
  @const AUDIBLE = 0.5  @ 687

# Private functions
  -- The box
  -- The strands
  -- The walk
  @fn strikesInOrder(strands)  @ 76-89
      -- Every strike, in onset order, lowest last — so a released chord leaves its
      -- bass to the sonority that follows (design/adaptive-tuning.md § The model).
  @fn sounding(strand, ppq)  @ 93-98
      -- Half-open, so a note released where the next is struck does not sound there,
      -- and a passage whose notes stop as the next begin reads as the last n struck.
  @fn promote(recent, strands, index)  @ 102-108
      -- The class holds one entry however many notes write it: a restrike moves its
      -- own entry to the front, and a second strand of the class takes the entry over.
  -- The objective
  -- The solve
  @fn schedule(strands, sonorities)  @ 156-182
      -- A strand is live from the onset it is chosen at to the last that reads it, both
      -- known before enumeration (§ Solving it), and listed in strand order for keying.
      @contract  strands, sonorities → per onset the strands born there, live there, and held from before  @ 155
  @fn assertAffordable(strands, plan)  @ 188-198
  @fn placementsAt(strands, born, strength)  @ 202-221
      -- Every combination of the shortlists of the strands born at an onset, with the
      -- pull each charges — the same against every state, so charged once here.
  @fn outranks(state, best, count, rankOf)  @ 226-234
      -- Cost, then the strands one by one, so an exact tie breaks deterministically rather than
      -- by table order (design/adaptive-tuning.md § What the solver takes).
      @contract  true iff `state` is the better of the two, the lower rank winning a tie  @ 225
  @fn byChoice(state, index)  @ 237-239
      -- Ranks a strand by the candidate index the solve chose for it.
  @fn keyOf(choice, list)  @ 241-245
  -- The springs
  -- The relaxation
  @fn tiesOf(spellings, free)  @ 355-365
      -- Where each spring would stand its two strands, given the other: i a delta below j, j a
      -- delta above i. Gathered once for the strands that sweep, since a held strand never reads its own ties: it stands as a constant in its neighbours'.
  @fn settle(ties, displacement, window, strength, stiffness)  @ 369-378
      -- One strand's optimum with the rest held: its springs' seats averaged against the pull,
      -- charged over the half-window the seats point it toward (design/adaptive-springs.md § The model).
  -- The candidates
  @fn joinCoords(coords, move)  @ 405-413
      -- A join's coords: the host's plus the move's, a cancelled prime dropped so two chains
      -- arriving at one spelling key alike (design/adaptive-springs.md § The candidates).
  @fn rebase(coords, from, to)  @ 417-426
      -- Coords are differences, so reading a member in another frame is one vector shift: what
      -- stood at `from` stands at `to`, a cancelled prime dropped as joinCoords drops it.
  @fn reachOf(deviation, window)  @ 430-432
      -- No note leaves the step it was notated on, and a spelling is placed as a whole, at one
      -- offset from the seats, so 'deviation' states which offsets remain open (design/adaptive-springs.md § The candidates).
  @fn coordString(coords)  @ 435-441
      -- Coords in one order, so two tables holding the same exponents read alike.
  @fn tokenOf(placed)  @ 445-447
      -- What a state has made of a member: the coords it was spelled at, and the component it
      -- joined into, so a member in a component of its own reads apart from the same coords tied in.
  @fn joinCost(state, component, placed, stiffness)  @ 451-463
      -- What a join costs where it lands: the box its component widens by, and a spring against
      -- each member already there, both priced before any displacement moves (§ The candidates).
  @fn admit(reached, seen, state, slot, placed, stiffness, lo, hi)  @ 469-485
      -- Keyed before it is built, so a candidate repeating a spelling costs its coords and its
      -- key alone; the state it would have extended is copied only where the spelling is new.
  @fn byScore(a, b)  @ 489-492
      -- Score, then the spelling itself, so an exact tie breaks on the coords rather than on
      -- table order, as sonority.solveToPoints breaks its own.
  @fn beamOver(seat, window, moves, width, stiffness)  @ 498-543
      -- One round per member after the anchor, each joined by one move to a member already
      -- placed; the unison is no join, and a state that can place nobody dies where it stands.
      @invariant  every state ties every member; an untied member states nothing, so charges nothing  @ 496
      @invariant  the reach is read against the spelling's own offset, not which member anchors  @ 497
  @fn chargeOf(members, seat, placed)  @ 549-578
      -- What coords and seats state about a set of members: a spring per pair of a component,
      -- tied in member order as sonority.springs ties them, and the box a component carries.
      @contract  members, seat per strand, coords and component per placed member → springs, box  @ 547
      @contract  a member the map lacks is one still waiting, which states nothing and is passed over  @ 548
  @fn spellingOf(state, members, present, seat, waiting)  @ 582-591
      -- The state read back as the sonority's own: its members' coords under the strands they
      -- name, and what those state charged as any set of placed members is charged.
  -- The terms
  -- The search
  @fn visibleAhead(onsets)  @ 691-698
      -- The strands a later onset names, which is all a continuation can read of an answer:
      -- what nothing ahead names is settled, however the answer arrived at it.
  @fn placementKey(members, placed, waiting)  @ 703-729
      -- What a sonority has been spelled as, however the spelling was reached: each component
      -- read from its earliest member, as chargeOf reads it, and the members still waiting.
      @invariant  two placements under one key charge alike, so a wait reaching one is no second road  @ 702
  @fn offeredBy(onsets, spellings)  @ 733-744
      -- What each onset's beam returned, read as placements: the spellings a wait may not come
      -- back with, taken from what the beam kept rather than what its moves could have reached.
  @fn answerKey(displacement, ahead, onsets, held)  @ 748-769
      -- An answer under the whole of what a continuation can tell it by: its cents at the strands
      -- ahead rounded to where two of them stop being two, and the deferrals it has yet to pay.
  @fn complete(entry, members, spelling)  @ 774-817
      -- What a spelling makes of a sonority still waiting: a waiter it places takes coords in the
      -- held sonority's frame through a member the two share, alone where they share none.
      @invariant  a waiter reaching two components merges them, every member shifted into the one frame  @ 773
  @fn heldBy(spelling)  @ 821-826
      -- The entry a spelling that defers opens: what it placed, whom it left, and what it has
      -- been charged so far, with the first component id its waiters may stand alone under.
  @fn extend(answer, spelling, onsets, at, seat, window, strength, stiffness, offered)  @ 831-860
      -- One answer extended by one spelling: the springs and box it has paid, each sonority it
      -- still holds charged again for what this spelling places, the onset's own strands relaxed.
      @contract  nil where a wait comes back with a placement its own sonority offered (§ The candidates)  @ 830

# Public API (sonority.*)
  @api sonority.score(coordSet)  @ 19-34
      -- The axes are gathered before any is measured, so an axis no member names doesn't reach
      -- back to 0; the spans are the octave-free lcm/gcd's coords, whose height tuning.height gives.
      @contract  coords[] → tuning.height of the coords of the set's octave-free lcm/gcd  @ 18
  @api sonority.strands(notes, classOf)  @ 42-70
      -- Notes of a class that overlap hold one tuning (§ The strand); the running
      -- release is half-open, so a note struck at a release starts another.
      @contract  notes, classOf → a Strand per class per run of overlapping notes, shortlists unfilled  @ 40
      @contract  grouped by ascending class, each in strike order, whatever order the notes arrive in  @ 41
  @api sonority.walk(strands, n)  @ 113-128
      -- The whole onset is absorbed before the sonority is taken, so a chord wider
      -- than n leaves its own lowest notes standing rather than its predecessor's.
      @contract  strands, n → a Sonority per onset: last n distinct classes struck, plus sounding  @ 112
  @api sonority.cost(strands, n, strength, choice)  @ 135-149
      -- The pull is counted once per strand rather than once per note, so an octave
      -- doubling changes no answer: the box already charges it nothing.
      @contract  strands, n, strength, choice → box over the walk + strength × strain² per strand  @ 134
  @api sonority.solveToPoints(strands, n, strength)  @ 251-296
      -- The state carries the whole choice vector rather than a backpointer: two
      -- generations are alive at a time and the budget bounds them.
      @invariant  reads no cents and knows no ratios — coords/strikes/releases/classes → indices  @ 249
      @contract  strands, n, strength → the index per strand minimising sonority.cost, exactly  @ 250
  @api sonority.springs(members, seat, spelling)  @ 305-319
      -- Each member's pure position is the first's seat plus its coords' cents; a spring's delta
      -- is the difference of the nearest-octave gaps to each seat (design/adaptive-springs.md § The model).
      @contract  members, spelling per member; seat per strand → a Spring per pair, i before j  @ 303
      @contract  springs alone: a spelling's box is sonority.score(spelling), charged where it is chosen  @ 304
  @api sonority.springCost(spellings, displacement, window, strength, stiffness)  @ 330-345
      -- The box is no part of this: a constant once the spellings are chosen, so it is charged
      -- where they are chosen rather than where the displacements are priced.
      @contract  spellings (a sonority.springs list per sonority), displacement and window per strand  @ 328
      @contract  → stiffness × (mistuning/50)² per spring + strength × strain² per half-window  @ 329
  @api sonority.relax(spellings, window, strength, stiffness, start, free)  @ 384-399
  @api sonority.spellings(members, seat, window, mayWait, moves, width, stiffness)  @ 600-641
      -- A waiting member states no interval, so the beam runs once per set of members left
      -- waiting; a deferral is no rival to a spelling, so the cut runs within a set (§ The candidates).
  @api sonority.seats(strands, notation)  @ 648-656
      -- One window serves a strand in every register, so notes[1] speaks for all of them; the
      -- seat keeps the register it was written in, which tuning.gapTo quotients out again.
      @contract  strands, notation → the cents of each strand's written step, and its window either side  @ 647
  @api sonority.onsets(strands, sonorities)  @ 663-681
      -- A member is free to wait while an onset it sounds through is still to come; at that onset
      -- it places or the state fails (design/adaptive-springs.md § The candidates).
      @contract  strands, sonorities → an Onset per sonority, its members the walk's own  @ 661
      @contract  a member the sonority holds by recency has stopped: it neither sounds nor waits  @ 662
  @api sonority.search(onsets, spellings, seat, window, strength, stiffness, cap)  @ 873-907
      -- The cost is taken over every spring accumulated so far rather than the onset's own, so
      -- a spelling is priced against the past it is chosen behind (§ The solve).
  -- The placement
  @api sonority.solveToMoves(strands, n, strength, notation, moves)  @ 915-917
      -- The moves facility's solve: the target read as intervals between strands rather than
      -- as points. The lattice search that stood here is retired, and the springs solve lands
      -- in its place (design/adaptive-springs.md § Where it sits).
      @contract  strands, n, strength, notation, moves → nil, until the springs solve lands  @ 914

